// Рассчитываем период
const today = new Date();
const yesterday = new Date(today);
yesterday.setDate(yesterday.getDate() - 1);

const periodStart = new Date('2026-01-01');
const periodEnd = yesterday;

const periodStartTimestamp = Math.floor(periodStart.getTime() / 1000);
const periodEndTimestamp = Math.floor(periodEnd.getTime() / 1000) + 86399;

console.log(`📅 Агрегация с ${periodStart.toISOString().split('T')[0]} по ${periodEnd.toISOString().split('T')[0]}`);

return {
  json: {
    period_start: periodStart.toISOString().split('T')[0],
    period_end: periodEnd.toISOString().split('T')[0],
    period_start_timestamp: periodStartTimestamp,
    period_end_timestamp: periodEndTimestamp,
    yesterday_date: yesterday.toISOString().split('T')[0],
    today_date: today.toISOString().split('T')[0]
  }
};

// Получить подписчиков за вчерашний день
const periodData = $('📅 Рассчитать период').first().json;
const yesterday = periodData.yesterday_date;
const url = `https://pyscczcuersdjvpmkiec.supabase.co/rest/v1/daily_data?project_id=eq.64c94e87-630c-470e-8ab1-8f7c8c835efa&date=eq.${yesterday}&select=followers`;

console.log(`🔗 Получить подписчиков за ${yesterday}`);

return { json: { url: url, yesterday: yesterday, ...periodData } };

// Агрегировать данные подписчиков из всех источников
const allInputs = $input.all();

let todayFollowers = 0;
let yesterdayFollowers = 0;
let periodData = null;

// Разбираем входные данные по типам
for (const input of allInputs) {
  const data = input.json;

  // Данные периода
  if (data.period_start && data.period_end) {
    periodData = data;
  }

  // Данные подписчиков сегодня
  if (data.followers_count !== undefined) {
    todayFollowers = data.followers_count;
  }

  // Данные подписчиков вчера (из базы)
  if (Array.isArray(data) && data.length > 0 && data[0].followers !== undefined) {
    yesterdayFollowers = data[0].followers || 0;
  }
}

// Вычисляем новых подписчиков
const newFollowers = Math.max(0, todayFollowers - yesterdayFollowers);

const yesterday = periodData ? periodData.yesterday_date : 'неизвестно';

console.log(`\n=== ПОДСЧЕТ НОВЫХ ПОДПИСЧИКОВ ===`);
console.log(`📅 Дата: ${yesterday}`);
console.log(`👥 Сегодня: ${todayFollowers.toLocaleString('ru-RU')}`);
console.log(`👥 Вчера: ${yesterdayFollowers.toLocaleString('ru-RU')}`);
console.log(`➕ Новых: ${newFollowers.toLocaleString('ru-RU')}`);

return {
  json: {
    project_id: '64c94e87-630c-470e-8ab1-8f7c8c835efa',
    date: yesterday,
    followers_today: todayFollowers,
    followers_yesterday: yesterdayFollowers,
    new_followers: newFollowers
  }
};

// Получаем посты из базы
const periodData = $('📅 Рассчитать период').first().json;
const url = `https://pyscczcuersdjvpmkiec.supabase.co/rest/v1/instagram_posts_stats?project_id=eq.64c94e87-630c-470e-8ab1-8f7c8c835efa&posted_at=gte.${periodData.period_start}&posted_at=lte.${periodData.period_end}&order=posted_at.asc`;

console.log(`🔗 URL: ${url}`);

return { json: { url: url, ...periodData } };

// Обрабатываем посты
const postsResponse = $input.first().json;
let posts = [];

if (Array.isArray(postsResponse)) {
  posts = postsResponse;
} else if (postsResponse.data && Array.isArray(postsResponse.data)) {
  posts = postsResponse.data;
}

console.log(`📊 Найдено постов: ${posts.length}`);

// Считаем метрики публикаций
const publications = posts.filter(p => {
  const mediaType = (p.media_type || '').toLowerCase();
  return !mediaType.includes('story') && mediaType !== 'stories';
}).length;

const totalReach = posts.reduce((sum, p) => sum + (p.reach || 0), 0);
const totalComments = posts.reduce((sum, p) => sum + (p.comments || 0), 0);
const totalLikes = posts.reduce((sum, p) => sum + (p.likes || 0), 0);
const totalShares = posts.reduce((sum, p) => sum + (p.shares || 0), 0);
const totalDiagnostics = posts.reduce((sum, p) => sum + (p.leads_count || 0), 0);
const totalSales = posts.reduce((sum, p) => sum + (p.paid_leads || 0), 0);
const totalRevenue = posts.reduce((sum, p) => sum + (p.revenue || 0), 0);

return {
  json: {
    posts_count: posts.length,
    publications: publications,
    reach: totalReach,
    comments: totalComments,
    likes: totalLikes,
    shares: totalShares,
    diagnostics: totalDiagnostics,
    sales: totalSales,
    revenue: Math.round(totalRevenue)
  }
};

// Получаем данные из входного потока
let postsData = null;
let followersData = null;
let periodData = null;
let newFollowersData = null;

const allInputs = $input.all();

for (const input of allInputs) {
  const data = input.json;
  if (data.period_start && data.period_end && data.period_start_timestamp) {
    periodData = data;
  } else if (data.followers_today !== undefined) {
    newFollowersData = data;
  } else if (data.posts_count !== undefined) {
    postsData = data;
  }
}

if (!periodData) {
  try { periodData = $('📅 Рассчитать период').first().json; } catch (e) {}
}
if (!newFollowersData) {
  try { newFollowersData = $('🧮 Агрегировать подписчиков').first().json; } catch (e) {}
}
if (!postsData) {
  try { postsData = $('🔍 Обработать посты').first().json; } catch (e) {}
}

const currentFollowers = newFollowersData ? (newFollowersData.followers_today || 0) : 0;
const newFollowers = newFollowersData ? (newFollowersData.new_followers || 0) : 0;
const postsCount = postsData ? (postsData.posts_count || 0) : 0;
const publications = postsData ? (postsData.publications || 0) : 0;
const reach = postsData ? (postsData.reach || 0) : 0;
const comments = postsData ? (postsData.comments || 0) : 0;
const diagnostics = postsData ? (postsData.diagnostics || 0) : 0;
const sales = postsData ? (postsData.sales || 0) : 0;
const revenue = postsData ? (postsData.revenue || 0) : 0;

console.log(`\n=== АГРЕГАЦИЯ ЗА ${periodData ? periodData.yesterday_date : 'неизвестно'} ===`);
console.log(`📊 Постов: ${postsCount}`);
console.log(`📈 Публикаций: ${publications}`);
console.log(`👥 Подписчиков: ${currentFollowers.toLocaleString('ru-RU')} (+${newFollowers.toLocaleString('ru-RU')} новых)`);
console.log(`📊 Охват: ${reach.toLocaleString('ru-RU')}`);
console.log(`💬 Комментарии: ${comments}`);
console.log(`🏥 Диагностики: ${diagnostics}`);
console.log(`💰 Выручка: ${revenue.toLocaleString('ru-RU')}₸`);

return {
  json: {
    project_id: '64c94e87-630c-470e-8ab1-8f7c8c835efa',
    period_start: periodData ? periodData.period_start : null,
    period_end: periodData ? periodData.period_end : null,
    publications: publications,
    reach: reach,
    comments: comments,
    followers: currentFollowers,
    new_followers: newFollowers,
    diagnostics: diagnostics,
    sales: sales,
    revenue: revenue
  }
};

const saveResult = $('💾 Сохранить статистику').first().json;
const followersSaveResult = $('💾 Записать подписчиков в daily_data').first().json;
const data = $('🧮 Агрегировать данные').first().json;
const followersData = $('🧮 Агрегировать подписчиков').first().json;

const statsSuccess = saveResult.statusCode >= 200 && saveResult.statusCode < 300;
const followersSuccess = followersSaveResult.statusCode >= 200 && followersSaveResult.statusCode < 300;

console.log(`\n=== РЕЗУЛЬТАТ СОХРАНЕНИЯ ===`);
console.log(`📊 Статистика: ${statsSuccess ? '✅ УСПЕХ' : '❌ ОШИБКА'}`);
console.log(`👥 Подписчики: ${followersSuccess ? '✅ УСПЕХ' : '❌ ОШИБКА'}`);
console.log(`📅 Дата: ${followersData.date}`);
console.log(`👥 Новых подписчиков: ${followersData.new_followers.toLocaleString('ru-RU')}`);
console.log(`📈 Метрики сохранены в content_production_stats и daily_data`);

if (statsSuccess && followersSuccess) {
  console.log(`\n🎉 Автоматическая агрегация Instagram данных завершена!`);
} else {
  console.log(`\n❌ Ошибки сохранения:`);
  if (!statsSuccess) console.log(`   Статистика: ${JSON.stringify(saveResult, null, 2)}`);
  if (!followersSuccess) console.log(`   Подписчики: ${JSON.stringify(followersSaveResult, null, 2)}`);
}

return { json: { success: statsSuccess && followersSuccess, ...data, followers: followersData } };
